/* One trainer record and one focused editor. */
(()=>{
 const root=document.querySelector('.tp-window'),workspace=root?.querySelector('.tp-workspace');if(!workspace)return;let state={};try{state=JSON.parse(localStorage.getItem('profile.v1')||'{}')}catch{}
 const make=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e};
 const home=make('section','tp-trainer-home');workspace.append(home);const bar=make('div','tp-focused-bar'),back=make('button','tp-return-record','‹ Aplicativos'),label=make('label','','Editar'),select=make('select');select.setAttribute('aria-label','Categoria da edição');
 const kinds=[['trainer','Treinador'],['partner','Parceiro'],['frame','Moldura'],['title','Título'],['trail','Rastro'],['emote','Emotes'],['victory','Comemoração'],['arena','Cenário'],['achievement','Conquistas']];for(const [id,text]of kinds){const o=make('option','',text);o.value=id;select.append(o)}label.append(select);bar.append(back,label);workspace.prepend(bar);
 const scene=root.querySelector('.tp-scene'),sceneAnchor=document.createComment('trainer-preview');scene.before(sceneAnchor);
 function show(){root.classList.add('tp-at-home');root.removeAttribute('data-edit-kind');refresh()}function edit(kind){sceneAnchor.after(scene);root.classList.remove('tp-at-home');root.dataset.editKind=kind;select.value=kind;const page=['trainer','partner'].includes(kind)?'trainer':kind==='achievement'?'achievements':'style';root.querySelector('[data-main-page="'+page+'"]').click();root.querySelector('.tp-collections').scrollTop=0;}
 back.onclick=show;select.onchange=()=>edit(select.value);
 function refresh(){home.replaceChildren();const heading=make('header','tp-tablet-heading');heading.append(make('small','','POKÉDEX · SISTEMA DO TREINADOR'),make('h2','',state.name||'Treinador'),make('p','','KANTO / CARTEIRA DA LIGA'));const hero=make('section','tp-digital-hero'),identity=make('div','tp-digital-identity');identity.append(heading);const profileTitle=window.TRAINER_PROFILE_REWARDS?.titles.find(t=>t.id===state.title);if(profileTitle&&state.title!=='none')identity.append(make('span','tp-home-title',profileTitle.name));const badges=root.querySelector('aside .tp-badge-case');if(badges){const row=badges.cloneNode(true);row.classList.add('tp-digital-badges');const badgePanel=make('section','tp-home-badge-panel');badgePanel.setAttribute('aria-label','Insígnias de Kanto');const badgeHead=make('div','tp-home-badge-heading');badgeHead.append(make('span','','INSÍGNIAS DE KANTO'),make('strong','',badges.querySelectorAll('.is-earned').length+' / 8'));badgePanel.append(badgeHead,row);const progress=make('div','tp-home-badge-track');const fill=make('i');fill.style.width=(badges.querySelectorAll('.is-earned').length/8*100)+'%';progress.append(fill);badgePanel.append(progress,make('small','',badges.querySelectorAll('.is-earned').length===8?'Circuito de ginásios concluído':'Sua jornada pelos ginásios de Kanto'));hero.append(badgePanel)}hero.prepend(scene,identity);home.append(hero);
 const apps=[['trainer','Treinador','Escolha seu personagem','T'],['partner','Parceiro','Seu companheiro de jornada','P'],['frame','Cartão','Moldura do seu perfil','▣'],['title','Títulos','Sua identidade na Liga','★'],['arena','Arenas','Cenários e missões','⬡'],['achievement','Conquistas','Marcos e recompensas','◆'],['emote','Emotes','Suas expressões','!'],['victory','Vitória','Sua comemoração','✦'],['trail','Pokébolas','Rastros das conquistas','·']];
 const grid=make('nav','tp-app-grid');grid.setAttribute('aria-label','Aplicativos do terminal');for(const [kind,name,description,glyph]of apps){const app=make('button','tp-app tp-app-'+kind),icon=make('span','tp-app-icon'),title=make('strong','',name),desc=make('small','',description);icon.setAttribute('aria-hidden','true');let art=null;if(kind==='trainer')art=root.querySelector('[data-option="trainer:'+state.trainer+'"] .tp-mini')?.cloneNode(true);if(kind==='partner'&&state.partner&&window.TRAINER_PARTNER_SPRITES)art=TRAINER_PARTNER_SPRITES.create(state.partner,'');if(kind==='achievement'){art=make('img');art.src=BADGE(1);art.alt=''}if(!art){const option=root.querySelector('[data-grid="'+kind+'"] .tp-choice[aria-pressed="true"]')||root.querySelector('[data-grid="'+kind+'"] .tp-choice');const original=option?.firstElementChild;if(original){art=original.cloneNode(true);if(original.tagName==='CANVAS')art.getContext('2d').drawImage(original,0,0)}}if(art)icon.append(art);else icon.append(make('b','',glyph));const current=root.querySelector('[data-current="'+kind+'"]')?.textContent;desc.textContent=kind==='arena'?root.querySelector('.tp-arena-background select option:checked')?.textContent||'Cenários e missões':current?.replace('Em uso · ','')||description;const meta=make('span','tp-app-meta',kind==='arena'?root.querySelector('.tp-arena-mission small:last-child')?.textContent||'Missões de exploração':(root.querySelector('[data-zone-count="'+kind+'"]')?.textContent||'')+' na coleção');app.append(icon,title,desc,meta);app.onclick=()=>edit(kind);grid.append(app)}home.append(grid);
 const dock=make('footer','tp-tablet-dock');const progress=root.querySelector('.tp-profile-stats');for(const child of progress.children)dock.append(child.cloneNode(true));home.append(dock);
 }
 function moveArena(){const picker=root.querySelector('.tp-arena-background'),mission=root.querySelector('.tp-arena-mission');if(!picker)return;let section=root.querySelector('.tp-arena-editor');if(!section){section=make('section','tp-arena-editor');section.append(make('h2','','Cenário do cartão'),make('p','','Escolha onde sua dupla aparece. Os cenários bloqueados mostram a missão necessária.'));root.querySelector('.tp-collections').append(section)}section.append(picker);if(mission)section.append(mission)}
 addEventListener('trainer-card-arena-ready',moveArena);addEventListener('trainer-profile-change',e=>{state={...e.detail};if(root.classList.contains('tp-at-home')&&!root.classList.contains('tp-in-application'))refresh()});show();
})();
